trial.program_source:
def transform(grid):
    out=[r[:] for r in grid]
    h=len(grid); w=len(grid[0])
    # The green cross links four blocks; remove its upper and lower blocks.
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==3]
    if not pts: return out
    lo=min(r for r,c in pts); hi=max(r for r,c in pts)
    for r in range(h):
        for c in range(w):
            if r<lo or r>hi:
                out[r][c]=0
    return out

